// Doanh thu bán hàng gom theo đối tác (phần lớn là công ty bảo hiểm) — xem đối tác nào
// đóng góp doanh thu nhiều nhất trong tháng, phục vụ đàm phán hợp tác lâu dài.
const d = $json;
const partners = d.partners || [];
const vnd = n => new Intl.NumberFormat('vi-VN').format(n || 0) + '₫';

const rows = partners.map((p, i) => `<tr><td>${i + 1}</td><td>${p.partner_name}</td><td align="right">${p.count}</td><td align="right"><b>${vnd(p.total_amount)}</b></td></tr>`).join('');

const html = `<h2>📊 Top ${partners.length} đối tác theo doanh thu — ${d.period_label}</h2>`
  + `<p>Tổng ${d.total_count} hoá đơn, doanh thu <b>${vnd(d.total_amount)}</b>.</p>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><th>#</th><th>Đối tác</th><th>Số hoá đơn</th><th>Doanh thu</th></tr>${rows}</table>`
  + `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `📊 Doanh thu theo đối tác — ${d.period_label} — tổng ${vnd(d.total_amount)}`,
  email_html: html
} };
